sql_query:
SELECT "Name of ICI"
FROM clinical_trials
WHERE "Included in MA" = 'No' AND "Monotherapy/combination" = 'Combination' AND "Trial phase" = 'Phase 2';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Name of ICI" AS source_value FROM clinical_trials WHERE "Included in MA" = 'No' AND "Monotherapy/combination" = 'Combination' AND "Trial phase" = 'Phase 2'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_ici_brand_name(source_value) AS "brand_name"
FROM base;
